# -*- coding: utf-8 -*-
# 生物補充題庫（v2，已對照原題避免重複）：每卷 +2 題→每節 30 題。
EXTRA = {
'a1-1':{'基礎卷':[('細菌屬於生物嗎？','是','由細胞組成：細菌雖然構造簡單、只有一個細胞，但具備生命現象，是由細胞組成的生物'),('生物體內化學反應的總稱是？','代謝','代謝：生物體內進行的所有化學反應（如分解養分、合成物質）合稱代謝')],
 '進階卷':[('青蛙冬眠以度過寒冬屬哪種生命現象？','適應','適應：青蛙靠冬眠降低身體活動、減少能量消耗來度過寒冬，這是生物因應環境變化的適應現象'),('生物死亡後還有生命現象嗎？','沒有','停止：生物死亡後不會呼吸、生長、繁殖，所有生命現象都會停止')],
 '挑戰卷':[('列舉三項生物共有的生命現象？','營養、生殖、感應等','列舉：生物共有的生命現象包括攝取營養、行呼吸、生長發育、生殖繁衍、對刺激產生感應等，任舉三項即可'),('為何病毒介於生物與非生物之間？','有遺傳物質但需寄主才能繁殖','特殊：病毒具有遺傳物質，看似有生命，但自己無法獨立進行代謝與繁殖，必須靠寄生在寄主細胞內才能複製，所以性質介於生物和非生物之間')]},
'a1-2':{'基礎卷':[('生物體由一個或多個什麼組成？','細胞','組成：所有生物體都是由一個或多個細胞所構成的，細胞是生物體最基本的構造單位'),('植物細胞儲水的大構造是？','大液泡','液泡：植物細胞內有一個很大的液泡，能儲存水分和養分，並幫助維持細胞的形狀')],
 '進階卷':[('顯微鏡總放大倍率如何計算？','目鏡×物鏡','倍率：顯微鏡的總放大倍率＝目鏡倍率乘以物鏡倍率，例如目鏡10倍、物鏡40倍，總倍率就是400倍'),('製作玻片標本的目的是？','便於顯微鏡觀察','標本：把樣本製成薄薄的玻片標本，可以讓光線穿透樣本，方便放在顯微鏡下觀察內部構造')],
 '挑戰卷':[('為何多數細胞體積都很小？','利於物質快速進出交換','大小：細胞越小，表面積相對於體積的比例越大，養分、氧氣等物質才能更快速地進出細胞、完成交換，所以大多數細胞體積都很小'),('植物細胞失水時大液泡會如何？','縮小使細胞失去膨壓','液泡：植物細胞缺水時，液泡裡的水分減少而縮小，細胞失去原本撐起來的膨壓，看起來就會枯萎軟垂')]},
'a1-3':{'基礎卷':[('胃屬於哪個組成層次？','器官','器官：胃是由多種組織組合而成、能執行消化功能的構造，屬於器官這個層次'),('血液屬於哪個組成層次？','組織','結締組織：血液是由許多相同或相似的細胞（血球）加上血漿構成，共同執行運輸功能，屬於結締組織')],
 '進階卷':[('神經細胞集合成什麼層次？','組織','組織：許多構造和功能相似的神經細胞聚集在一起，就形成神經組織，負責傳遞訊息'),('植物的根屬於哪個層次？','器官','器官：根是由多種組織（如表皮、輸導組織等）組合而成、負責吸收水分養分的構造，屬於器官')],
 '挑戰卷':[('以植物根為例說明其組成層次？','由多種組織構成的器官','植物：根本身是器官，由表皮組織、輸導組織等多種組織組合而成，這些組織又是由許多細胞構成，層層組合形成完整的根'),('為何多細胞生物需要組織分工？','提升效率執行複雜功能','分工：不同組織各自負責特定的工作，彼此分工合作，能讓生物體更有效率地完成複雜的生理功能，比單一細胞獨自運作更有效')]},
'a2-1':{'基礎卷':[('缺乏會導致貧血的礦物質是？','鐵','礦物質：鐵是合成血紅素的重要原料，長期缺鐵會使紅血球攜氧能力下降，造成貧血'),('缺乏會影響骨骼牙齒的礦物質？','鈣','礦物質：鈣是構成骨骼和牙齒的主要成分之一，缺鈣會使骨骼牙齒發育不良、變得脆弱')],
 '進階卷':[('唾液中的消化酵素分解哪種養分？','澱粉','澱粉酶：唾液中含有澱粉酶，能把食物中的澱粉分解成較小的醣類分子'),('酵素作用有最適的什麼條件？','溫度與酸鹼','最適：每種酵素都有最適合作用的溫度和酸鹼度，在這個條件下酵素的作用效率最高，超過範圍效率就會下降')],
 '挑戰卷':[('為何冰箱冷藏能延長食物保存？','低溫降低酵素與微生物活性','溫度：低溫會降低食物中酵素的作用速率，也抑制微生物的生長繁殖，兩者共同減緩食物腐敗的速度'),('酵素是蛋白質對高溫敏感的原因？','高溫使蛋白質變性','變性：酵素的本質是蛋白質，遇到高溫時蛋白質的立體結構會被破壞（變性），導致酵素永久失去作用能力')]},
'a2-2':{'基礎卷':[('光合作用需要哪種光？','陽光(可見光)','光：植物行光合作用需要吸收陽光中的可見光作為能量來源，把光能轉換成化學能'),('葉的綠色來自哪種色素？','葉綠素','色素：葉綠體中含有葉綠素，能吸收光能進行光合作用，也使葉子呈現綠色')],
 '進階卷':[('光合作用主要在葉的哪種細胞進行？','葉肉細胞(含葉綠體)','部位：葉肉細胞內含有大量葉綠體，是進行光合作用最主要的場所'),('植物長期缺光葉子可能？','變黃(黃化)','缺葉綠素：植物長期缺乏光照，無法正常製造葉綠素，葉子會因此變黃，這種現象稱為黃化')],
 '挑戰卷':[('為何水生植物白天在水中冒氣泡？','光合作用釋出氧','放氧：水生植物白天行光合作用會產生氧氣，多餘的氧氣以氣泡的形式從葉片排出，在水中可以看到一顆顆小氣泡'),('比較植物在強光與弱光下的光合速率？','強光較快至飽和','光強：光線越強，光合作用的速率通常越快，但當光線強度達到一定程度後，速率會趨於穩定不再增加，稱為光飽和')]},
'a2-3':{'基礎卷':[('膽汁由哪個器官分泌？','肝臟','附屬：膽汁是由肝臟分泌、暫存在膽囊，屬於消化系統的附屬器官所產生的分泌物'),('消化道靠什麼運動推送食物？','蠕動','肌肉：消化道管壁的肌肉會規律收縮舒張，形成一波波的蠕動，把食物向前推送')],
 '進階卷':[('胰臟分泌的消化液進入哪個器官？','小腸','消化液：胰臟分泌的胰液含有多種消化酵素，會經由胰管送入小腸，幫助分解各種養分'),('養分吸收後由什麼運送全身？','血液','運送：小腸吸收的養分進入微血管後，會隨著血液循環被運送到身體各處供細胞利用')],
 '挑戰卷':[('膽汁不含酵素卻助消化脂肪的原因？','乳化脂肪增大接觸面積','乳化：膽汁本身不含消化酵素，但能把大團的脂肪乳化成許多小油滴，增加脂肪與酵素接觸的表面積，讓酵素能更有效地分解脂肪'),('暴飲暴食為何易消化不良？','超過消化系統負荷','保健：短時間內吃下過多食物，超過消化系統能分泌的消化液與蠕動的處理能力，容易造成消化不良')]},
'a3-1':{'基礎卷':[('植物吸收水分主要靠哪個器官？','根','吸收：植物主要靠根部的根毛從土壤中吸收水分和溶於水中的礦物質'),('氣孔主要分布在葉的哪一面？','背面','葉背：多數植物的氣孔主要分布在葉片背面，可以減少陽光直射造成的水分散失')],
 '進階卷':[('蒸散作用會使植物散失什麼？','水分','失水：植物體內的水分經由氣孔以水蒸氣的形式散失到空氣中，這個過程稱為蒸散作用'),('木質部除運水還運送什麼？','溶於水的礦物質','礦物質：木質部除了運輸水分，也一併運送溶解在水中的礦物質，從根部往上輸送到植物各部位')],
 '挑戰卷':[('炎熱正午植物氣孔常關閉的原因？','減少蒸散避免過度失水','調節：正午氣溫高、蒸散作用旺盛，植物為了避免體內水分散失過多而缺水，會關閉部分氣孔來減少蒸散'),('為何砍斷莖的韌皮部果實難變甜？','養分無法運送到果實','運養：韌皮部負責運送葉片行光合作用製造的養分（如醣類）到植物各處，若韌皮部被破壞，養分無法送達果實，果實就難以累積糖分變甜')]},
'a3-2':{'基礎卷':[('血液中運送養分與廢物的液體成分是？','血漿','液體：血漿是血液中的液態成分，能溶解並運送養分、廢物、激素等物質到全身'),('心臟規律收縮舒張形成？','心跳','幫浦：心臟像幫浦一樣規律地收縮與舒張，把血液推送到全身，這個規律的搏動就是心跳')],
 '進階卷':[('動脈血壓較高所以管壁？','較厚有彈性','承壓：動脈要承受心臟收縮時較高的血壓，因此管壁演化得較厚、較有彈性，才能承受壓力變化'),('血液循環中氣體交換發生在？','微血管','交換：微血管管壁極薄，是氧氣與二氧化碳等氣體在血液與組織細胞之間進行交換的主要場所')],
 '挑戰卷':[('為何運動時心跳會加快？','加速運送氧與養分至肌肉','需求：運動時肌肉消耗更多氧氣與養分，心臟必須加快跳動速率，才能把足夠的血液更快送到肌肉，滿足身體需求'),('貧血與紅血球或血紅素不足的關係？','攜氧能力下降','攜氧：紅血球內的血紅素負責攜帶氧氣，若紅血球數量或血紅素不足，血液攜氧能力下降，就會造成貧血症狀')]},
'a3-3':{'基礎卷':[('免疫系統對抗的對象是？','病原體','防禦：免疫系統主要負責辨識並對抗入侵體內的病原體，如細菌、病毒等'),('接種疫苗屬於預防還治療？','預防','預防：疫苗是在還沒生病前，先讓身體產生免疫記憶，用來預防未來感染，屬於預防措施')],
 '進階卷':[('第一次感染後身體會留下？','免疫記憶','記憶：身體第一次接觸某種病原體後，免疫系統會保留對它的記憶，稱為免疫記憶，方便下次更快反應'),('過敏是免疫系統的什麼反應？','過度反應','免疫：過敏是免疫系統對原本無害的物質（如花粉）產生過度激烈的防禦反應，反而造成身體不適')],
 '挑戰卷':[('為何流感疫苗需要每年接種？','病毒株會變異','變異：流感病毒容易產生變異，每年流行的病毒株可能不同，先前的免疫記憶不一定能完全對抗新病毒株，所以需要每年接種更新的疫苗'),('免疫記憶如何讓二次感染較快康復？','快速產生大量抗體','記憶：由於身體已經留有對該病原體的免疫記憶，再次遇到同一種病原體時，能更快速地大量產生抗體加以清除，因此二次感染通常恢復得比較快')]},
'a4-1':{'基礎卷':[('腦與脊髓合稱？','中樞神經','中樞：腦和脊髓是神經系統中負責統整、下達指令的核心部分，合稱中樞神經'),('神經系統負責快速還緩慢傳訊？','快速','快速：神經系統以電訊號傳遞訊息，速度非常快，能讓身體迅速對刺激做出反應')],
 '進階卷':[('眨眼閃避異物屬於？','反射','保護：眨眼躲避異物是一種不經過大腦思考、由脊髓或腦幹直接處理的反射動作，能快速保護眼睛'),('大腦主管思考記憶屬中樞神經嗎？','是','中樞：大腦是中樞神經系統的一部分，負責思考、記憶、判斷等高階功能')],
 '挑戰卷':[('酒精影響神經系統可能造成？','反應變慢判斷力下降','影響：酒精會抑制神經系統的功能，使神經傳導變慢，導致反應遲鈍、判斷力下降，這也是酒後不能開車的原因'),('為何反射能在受傷前就反應？','脊髓直接處理不必等大腦','快速：反射動作的訊號傳到脊髓就直接下達指令，不需要先傳到大腦處理再傳回來，因此反應速度非常快，能在還沒受傷前就先做出保護動作')]},
'a4-2':{'基礎卷':[('胰島素由哪個器官分泌？','胰臟(胰島)','胰臟：胰島素是由胰臟中的胰島細胞所分泌，用來調節血糖濃度'),('內分泌訊息傳遞比神經？','慢但持久','持久：內分泌系統靠激素隨血液運送訊息，傳遞速度比神經慢，但作用效果通常比較持久')],
 '進階卷':[('甲狀腺激素分泌不足可能影響？','代謝變慢','代謝：甲狀腺激素能促進身體的新陳代謝，分泌不足會使代謝速率變慢，容易感到疲倦、怕冷'),('激素作用完後通常會？','被分解代謝','代謝：激素完成調節作用後，通常會被身體分解代謝掉，避免持續作用影響身體平衡')],
 '挑戰卷':[('糖尿病與胰島素的關係？','胰島素不足或失效使血糖過高','血糖：糖尿病患者體內胰島素分泌不足，或身體細胞對胰島素反應不佳，導致血糖無法被有效調節，長期偏高'),('為何內分泌適合長期調節、神經適合即時反應？','激素持久神經快速短暫','互補：神經系統用電訊號傳遞，反應快但作用短暫，適合處理緊急、即時的狀況;內分泌系統靠激素隨血液運送，作用較慢但效果持久，適合處理需要長時間維持的生理調節，兩者互相搭配')]},
'a4-3':{'基礎卷':[('血糖過低時身體會？','升高血糖','血糖：身體偵測到血糖過低時，會分泌激素促使血糖濃度回升，維持在正常範圍'),('排汗與排尿都幫助調節？','體內水分或體溫','調節：排汗有助於散熱調節體溫，排尿則能排出多餘水分與代謝廢物，兩者都是身體維持恆定的重要方式')],
 '進階卷':[('運動後大量流汗需補充？','水分與電解質','補充：大量流汗會使體內水分和電解質（如鈉、鉀）流失，運動後應適量補充水分和電解質，避免身體失衡'),('恆定讓體內維持在什麼狀態？','相對穩定','穩定：恆定作用能讓體內的溫度、血糖、水分等維持在一個相對穩定的範圍，不會隨外界劇烈變動')],
 '挑戰卷':[('發燒是否為體溫恆定失衡？','是','免疫致升溫：發燒其實是身體對抗病原體時，主動把體溫調節的基準點暫時調高，屬於體溫恆定機制被重新設定，並非完全失控'),('為何長時間曝曬易中暑？','散熱不及體溫失控上升','失恆：長時間曝曬在高溫環境下，身體散熱的速度跟不上吸收熱量的速度，體溫調節機制失去平衡，體溫持續上升就可能中暑')]},
'a5-1':{'基礎卷':[('細胞分裂使生物體？','生長','增殖：細胞經由分裂增加數目，是生物體生長發育的基礎'),('人體體細胞染色體有幾對？','23對','46條：人體一般體細胞內含有23對、共46條染色體')],
 '進階卷':[('有絲分裂常見於哪類細胞？','體細胞','體細胞：有絲分裂發生在體細胞，用來增加細胞數目、進行生長和修補，分裂後染色體數目不變'),('減數分裂後染色體數變為原來的？','一半','減半：減數分裂會使產生的生殖細胞（精子、卵）染色體數目減半，這樣受精後才能恢復成原本的染色體數目')],
 '挑戰卷':[('為何體細胞分裂要先複製染色體？','使兩子細胞各得完整一套','複製：細胞分裂前必須先把染色體複製一份，這樣分裂後產生的兩個子細胞才能各自獲得一套完整的染色體，維持遺傳訊息不變'),('若精卵不減半世代染色體會？','逐代倍增異常','後果：如果生殖細胞形成時染色體數目不減半，受精後染色體數目會加倍，一代一代下去染色體數目會不斷倍增，造成遺傳異常')]},
'a5-2':{'基礎卷':[('草莓走莖繁殖屬哪種生殖？','無性生殖','無性：草莓靠走莖長出新植株，不需要經過精卵結合，屬於無性生殖'),('有性生殖需要幾個親代？','通常兩個','雙親：有性生殖通常需要兩個親代（父方與母方）分別提供精細胞和卵細胞結合，才能產生後代')],
 '進階卷':[('無性生殖後代基因與親代？','幾乎相同','一致：無性生殖不經過基因重組，後代的基因幾乎和親代完全相同，等於是親代的複製品'),('嫁接繁殖屬哪種生殖？','無性生殖','無性：嫁接是把植物的一部分接到另一株植物上使其繼續生長，不涉及精卵結合，屬於無性生殖')],
 '挑戰卷':[('為何無性繁殖作物易受同種病害全滅？','基因相同缺乏抗性變異','風險：無性繁殖產生的個體基因幾乎完全相同，一旦出現某種病害，因為缺乏基因變異、抗病能力也相同，整批作物可能同時遭殃、全部滅絕'),('有性生殖如何增加後代多樣性？','雙親基因重組','重組：有性生殖時父母雙方的基因會重新組合，產生的後代基因組合和親代不完全相同，因此能增加後代的多樣性，有助於適應環境變化')]},
'a5-3':{'基礎卷':[('花的哪個部位接受花粉？','雌蕊(柱頭)','雌蕊：花粉落在雌蕊頂端的柱頭上，才能完成授粉，進一步發育出花粉管使精細胞到達胚珠'),('受精後子房發育成？','果實','果實：花朵受精後，子房會逐漸發育膨大形成果實，裡面的胚珠則發育成種子')],
 '進階卷':[('蟲媒花常靠什麼傳粉？','昆蟲','媒介：蟲媒花通常有鮮豔的花色和香氣，用來吸引昆蟲當媒介，幫忙把花粉從一朵花帶到另一朵花'),('體外受精常見於水生的？','魚類與兩生類','水中：魚類和兩生類（如青蛙）大多把精細胞和卵細胞排到水中在體外結合，這種方式稱為體外受精，需要靠水作為媒介')],
 '挑戰卷':[('花色鮮豔與香氣對傳粉的意義？','吸引昆蟲協助傳粉','吸引：花朵演化出鮮豔的顏色與濃郁的香氣，主要目的是吸引昆蟲等傳粉者前來，順道幫忙把花粉傳播到其他花朵，提高授粉成功率'),('為何體內受精受精率通常較高？','精卵在體內結合受保護','保護：體內受精時精細胞和卵細胞在母體內部結合，不受外界環境（如水流、乾燥）的影響與威脅，因此受精成功的機率通常比體外受精高')]},
'a6-1':{'基礎卷':[('控制生物性狀的遺傳因子稱？','基因','單位：基因是控制生物遺傳性狀的基本單位，會由親代傳遞給子代'),('一對基因分別來自？','父與母','雙親：生物體內控制同一性狀的一對基因，一個來自父親、一個來自母親')],
 '進階卷':[('純種顯性的基因型寫作？','AA','基因型：兩個都是顯性基因的組合寫成AA，代表純種顯性個體'),('Aa這種基因型稱為？','雜合(帶因)','雜合：一個顯性基因加一個隱性基因的組合稱為雜合子，外表雖表現顯性，但體內帶有隱性基因')],
 '挑戰卷':[('AA×Aa子代基因型與性狀？','AA與Aa皆表現顯性','雜交：AA只能提供顯性基因A，Aa能提供A或a，配對後子代基因型是AA或Aa，因為都至少有一個顯性A，所以全部都表現顯性性狀'),('為何帶因者外表看不出攜帶隱性基因？','顯性遮蓋隱性','遮蓋：帶因者(Aa)體內雖然有一個隱性基因a，但顯性基因A的表現會遮蓋住隱性基因，所以外表仍表現顯性性狀，看不出來帶有隱性基因')]},
'a6-2':{'基礎卷':[('決定人類性別的是哪對染色體？','性染色體','第23對：人類共23對染色體，其中最後一對（第23對）是性染色體，決定個體的性別'),('女性的兩條性染色體都是？','X','XX：女性的性染色體組成是兩條X染色體，寫成XX')],
 '進階卷':[('男性的性染色體組成為？','一X一Y','XY：男性的性染色體組成是一條X染色體和一條Y染色體，寫成XY'),('性聯遺傳的基因多位於哪條染色體？','X染色體','性聯：許多性聯遺傳的疾病基因位於X染色體上，因此遺傳表現常和性別有關')],
 '挑戰卷':[('女兒的兩條X染色體分別來自？','一條來自母一條來自父','來源：女兒的性染色體是XX，其中一條X來自母親，另一條X則來自父親（父親唯一的X染色體）'),('為何性染色體異常可能影響性別發育？','決定性別的基因異常','異常：性染色體上帶有決定性別發育的重要基因，若性染色體數目或結構異常，可能干擾這些基因的正常表現，進而影響性別發育')]},
'a6-3':{'基礎卷':[('DNA存在於細胞的哪個構造？','細胞核(染色體上)','核：DNA主要存在於細胞核內，纏繞成染色體的形式儲存遺傳訊息'),('遺傳訊息由親代傳給？','子代','遺傳：親代透過生殖過程把DNA所攜帶的遺傳訊息傳遞給下一代的子代')],
 '進階卷':[('輻射與化學物質可能誘發？','突變','誘變：某些輻射線或化學物質會破壞DNA的結構，使基因發生突變'),('基因決定生物的？','性狀','性狀：基因所攜帶的訊息，決定了生物表現出來的各種性狀，例如外觀、生理特徵等')],
 '挑戰卷':[('為何有些突變能遺傳給後代？','發生在生殖細胞','遺傳：如果突變發生在精子或卵這類生殖細胞裡，這個改變過的基因就有機會隨著受精傳遞給下一代;若突變只發生在體細胞，則不會遺傳給後代'),('基因改造食品引發疑慮的原因？','環境與食品安全等倫理考量','倫理：基因改造技術牽涉到對生態環境的長期影響、食品安全性評估，以及是否符合社會倫理等多方面考量，因此常引發討論與疑慮')]},
'a7-1':{'基礎卷':[('生物族群世代間性狀改變稱？','演化','演變：生物族群經過許多世代，遺傳性狀逐漸產生改變的過程稱為演化'),('天擇又稱？','適者生存','天擇：天擇的概念又稱適者生存，指環境會篩選出比較能適應的個體讓牠們存活繁衍')],
 '進階卷':[('化石通常保存在哪類岩石？','沉積岩','化石：生物遺骸經過長時間掩埋、礦化，多半保存在沉積岩中，成為研究演化的重要證據'),('長頸鹿脖子變長用天擇如何解釋？','長頸者較能取食存活繁殖','天擇：族群中原本脖子長短不一，脖子較長的個體較能吃到高處的葉子，存活與繁殖的機會較大，經過許多世代，脖子長的性狀就逐漸在族群中普遍起來')],
 '挑戰卷':[('為何抗生素濫用會加速抗藥菌？','殺死敏感菌留下抗藥菌繁殖','天擇：抗生素會殺死對藥物敏感的細菌，但少數原本就帶有抗藥性的細菌能存活下來並大量繁殖，長期濫用抗生素等於持續篩選，加速抗藥性細菌的出現'),('比較人為育種與自然天擇的選擇者？','育種由人天擇由環境','對比：人為育種是由人類依照需求主動挑選具有理想性狀的個體來繁殖;自然天擇則是由環境條件自然篩選出比較適應的個體存活繁衍，兩者的選擇者不同')]},
'a7-2':{'基礎卷':[('界門綱目科屬種中最小的是？','種','最小：生物分類階層由大到小依序是界、門、綱、目、科、屬、種，種是最小、最基本的分類單位'),('同一物種的個體能？','交配產生後代','種：同一物種的個體之間能夠互相交配，並產生具有生殖能力的後代，這是判斷是否為同一物種的重要依據')],
 '進階卷':[('學名由幾個部分組成？','兩個(屬名+種小名)','二名：生物學名採用二名法命名，由屬名加種小名兩部分組成，用來統一表示一個物種'),('親緣關係越近的生物分在？','越低的相同階層','親緣：分類階層越低（越接近種），代表生物之間的親緣關係越接近，例如同科的生物比同界的生物親緣關係更近')],
 '挑戰卷':[('為何不能只用外表相似來分類？','外表相似親緣未必接近','外表：有些生物外表看起來相似，但實際上親緣關係可能相差很遠（例如趨同演化），所以分類不能只靠外表，還要參考構造、遺傳等更多證據'),('二名法對全球科學交流的意義？','統一名稱避免混淆','統一：不同國家、語言對同一種生物可能有不同俗名，容易造成混淆，二名法提供全世界通用、統一的學名，方便科學家溝通交流')]},
'a8-1':{'基礎卷':[('同一區域不同物種族群的集合是？','群集','群集：在同一個區域內，各種不同物種的族群共同生活組成的整體，稱為群集'),('蜜蜂採花蜜同時助授粉屬？','互利共生','互利：蜜蜂採花蜜獲得食物，同時幫花朵傳播花粉，雙方都獲得好處，屬於互利共生的關係')],
 '進階卷':[('菟絲子吸取宿主養分屬？','寄生','寄生：菟絲子纏繞在其他植物上，吸取宿主的養分維生，對宿主有害，自己卻得利，這種關係稱為寄生'),('食物與空間有限時同種個體會？','競爭','競爭：當食物、空間等資源有限時，同一族群內的個體會互相競爭這些有限的資源')],
 '挑戰卷':[('引入缺乏天敵的外來種可能造成？','大量繁殖破壞平衡','入侵：外來種若在新環境中沒有天敵制衡，可能大量繁殖，與原生物種競爭資源，破壞當地原本的生態平衡'),('寄生與互利共生的差別？','寄生一方受害互利雙方得利','區別：寄生關係中一方（宿主）會受到傷害，另一方（寄生者）得利;互利共生則是雙方都能從關係中獲得好處，兩者對彼此的影響不同')]},
'a8-2':{'基礎卷':[('植物在生態系扮演的角色是？','生產者','生產者：植物能行光合作用自行製造養分，是生態系中的生產者，也是食物鏈的基礎'),('動物多屬於生態系的？','消費者','消費者：動物無法自行製造養分，必須攝食其他生物來獲取能量，屬於生態系中的消費者')],
 '進階卷':[('能量在食物鏈每一級大多如何？','大部分流失僅少部分傳遞','遞減：能量沿著食物鏈傳遞時，大部分會以熱能等形式散失，只有一小部分（通常約十分之一）會傳遞到下一營養級'),('缺少分解者生態系會？','物質無法循環','循環：分解者負責把動植物遺體和廢物分解成簡單物質歸還環境，若缺少分解者，物質就無法循環利用，生態系會逐漸失衡')],
 '挑戰卷':[('為何食物鏈通常不超過四五級？','能量逐級遞減不足支持','能量：能量沿食物鏈往上傳遞時每一級都大量流失，傳到第四、五級時剩下的能量已經很少，不足以再支持更高一級的生物族群生存，所以食物鏈通常不會太長'),('生產者大量減少對整個生態系的影響？','能量來源減少各階層受衝擊','連鎖：生產者是整個食物鏈能量的最初來源，一旦生產者大量減少，直接依賴它的消費者食物不足，會一層層向上影響到整個生態系的各個階層')]},
'a8-3':{'基礎卷':[('基因、物種、生態系三者合稱？','生物多樣性','三層：生物多樣性包含基因多樣性、物種多樣性、生態系多樣性三個層次，合稱生物多樣性'),('設立國家公園主要是為了？','保育生物多樣性','保護：設立國家公園的主要目的是保護當地的自然環境與野生動植物，維護生物多樣性')],
 '進階卷':[('引入強勢外來種對原生種？','造成競爭或排擠','入侵：強勢外來種可能與原生物種競爭食物、空間等資源，甚至直接排擠、捕食原生種，威脅原生物種的生存'),('復育瀕危物種的目的？','恢復其族群數量','復育：復育瀕危物種是希望透過人工繁殖、保護棲地等方式，幫助該物種的族群數量逐漸恢復，避免滅絕')],
 '挑戰卷':[('為何大面積單一栽培風險高？','缺乏多樣性易被病蟲害全毀','風險：大面積只種植同一種作物，一旦出現適合的病蟲害，因為缺乏基因與物種的多樣性，很容易在短時間內大範圍蔓延，造成整片作物全毀'),('氣候變遷如何加劇物種滅絕？','棲地改變物種來不及適應','變遷：氣候快速變遷會改變原本的棲地環境（如氣溫、降雨型態），許多物種的演化速度跟不上環境改變的速度，來不及適應就可能走向滅絕')]},
}
